package com.gameaggregator.webhookservice.application;import com.gameaggregator.webhookservice.domain.WebhookEndpoint;import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;import java.net.URI;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.HexFormat;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.springframework.stereotype.Component;@Component public class WebhookSender{final WebhookSecretCipher cipher;final HttpClient http=HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).build();public WebhookSender(WebhookSecretCipher c){cipher=c;}@CircuitBreaker(name="webhook")public int send(WebhookEndpoint e,String eventId,String payload)throws Exception{String secret=cipher.decrypt(e.encryptedSecret);Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String signature="sha256="+HexFormat.of().formatHex(mac.doFinal(payload.getBytes(StandardCharsets.UTF_8)));var req=HttpRequest.newBuilder(URI.create(e.url)).timeout(Duration.ofMillis(e.timeoutMs)).header("Content-Type","application/json").header("X-Webhook-Id",eventId).header("X-Webhook-Signature",signature).POST(HttpRequest.BodyPublishers.ofString(payload)).build();return http.send(req,HttpResponse.BodyHandlers.discarding()).statusCode();}}